import { useMemo, useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { CalendarDays, Check, ChevronLeft, ChevronRight, Clock3, Plus } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { AppPageHero } from "@/components/app/AppPageHero";
import { Button } from "@/components/ui/Button";
import { portalRepository } from "@/services/supabase/portal";
import { usePageMeta } from "@/hooks/usePageMeta";

function dateInputValue(date: Date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}

export default function AppointmentsPage() {
  usePageMeta("Rendez-vous du projet", "Demandez un créneau et retrouvez les rendez-vous liés au projet.");
  const client = useQueryClient();
  const { data, error } = useQuery({ queryKey: ["portal", "snapshot"], queryFn: portalRepository.getSnapshot });
  const firstPossibleDate = useMemo(() => { const date = new Date(); date.setDate(date.getDate() + 1); return date; }, []);
  const [month, setMonth] = useState(() => new Date(firstPossibleDate.getFullYear(), firstPossibleDate.getMonth(), 1));
  const [date, setDate] = useState(() => dateInputValue(firstPossibleDate));
  const [time, setTime] = useState("14:00");
  const [duration, setDuration] = useState(30);
  const [type, setType] = useState<"phone" | "video" | "onsite">("video");
  const [notes, setNotes] = useState("");
  const mutation = useMutation({ mutationFn: async () => { if (!data?.project) throw new Error("Aucun projet actif."); return portalRepository.requestAppointment(data.project.id, { startsAt: new Date(`${date}T${time}`).toISOString(), duration, type, notes }); }, onSuccess: async () => { setNotes(""); await client.invalidateQueries({ queryKey: ["portal", "snapshot"] }); } });
  const daysInMonth = new Date(month.getFullYear(), month.getMonth() + 1, 0).getDate();
  const offset = (new Date(month.getFullYear(), month.getMonth(), 1).getDay() + 6) % 7;
  const cells = Array.from({ length: offset + daysInMonth }, (_, index) => index < offset ? null : index - offset + 1);
  const appointmentDays = new Set((data?.appointments ?? []).filter((appointment) => { const value = new Date(appointment.startsAt); return value.getFullYear() === month.getFullYear() && value.getMonth() === month.getMonth(); }).map((appointment) => new Date(appointment.startsAt).getDate()));
  return <div className="mx-auto max-w-[1240px] space-y-5"><AppPageHero icon={CalendarDays} eyebrow="Rendez-vous" title={<>Vos échanges organisés <span className="gradient-text">autour du projet.</span></>} description="Vous demandez un créneau ; l’équipe le confirme ensuite. Aucun horaire affiché comme demandé n’est présenté comme garanti." stat={{ value: String(data?.appointments.length ?? 0), label: "Rendez-vous" }} />{error ? <Card className="p-5 text-[color:var(--blue)]">{error instanceof Error ? error.message : "Chargement impossible"}</Card> : null}<div className="grid gap-5 xl:grid-cols-[1fr_390px]"><div className="space-y-5"><Card className="p-5 sm:p-7"><div className="flex items-center justify-between"><button onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() - 1, 1))} className="grid size-10 place-items-center rounded-full border border-[var(--line)]" aria-label="Mois précédent"><ChevronLeft className="size-4" /></button><h2 className="text-xl font-semibold capitalize">{month.toLocaleDateString("fr-FR", { month: "long", year: "numeric" })}</h2><button onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() + 1, 1))} className="grid size-10 place-items-center rounded-full border border-[var(--line)]" aria-label="Mois suivant"><ChevronRight className="size-4" /></button></div><div className="mt-6 grid grid-cols-7 gap-1 text-center">{["L","M","M","J","V","S","D"].map((label, index) => <span key={`${label}-${index}`} className="py-2 text-[10px] font-bold text-[color:var(--muted)]">{label}</span>)}{cells.map((day, index) => day ? <button key={day} onClick={() => setDate(dateInputValue(new Date(month.getFullYear(), month.getMonth(), day)))} className={`relative grid min-h-12 place-items-center rounded-[14px] text-sm font-semibold transition ${date === dateInputValue(new Date(month.getFullYear(), month.getMonth(), day)) ? "bg-[var(--ink)] text-white" : "hover:bg-[var(--paper)]"}`}>{day}{appointmentDays.has(day) ? <span className="absolute bottom-1.5 size-1.5 rounded-full bg-[var(--mint)]" /> : null}</button> : <span key={`empty-${index}`} />)}</div></Card><Card className="overflow-hidden"><div className="border-b border-[var(--line)] p-5"><h2 className="text-2xl font-semibold">Historique et prochaines dates</h2></div><div className="divide-y divide-[var(--line)]">{[...(data?.appointments ?? [])].sort((a,b) => Date.parse(b.startsAt) - Date.parse(a.startsAt)).map((appointment) => <div key={appointment.id} className="flex items-center gap-4 p-5"><span className={`grid size-11 place-items-center rounded-[16px] ${appointment.status === "completed" ? "bg-[var(--mint)]" : "bg-[var(--paper)]"}`}>{appointment.status === "completed" ? <Check className="size-4" /> : <Clock3 className="size-4" />}</span><div className="flex-1"><p className="font-semibold">{new Date(appointment.startsAt).toLocaleString("fr-FR", { dateStyle: "long", timeStyle: "short" })}</p><p className="mt-1 text-xs text-[color:var(--muted)]">{appointment.type} · {appointment.status}</p></div></div>)}{data?.appointments.length === 0 ? <p className="p-10 text-center text-sm text-[color:var(--muted)]">Aucun rendez-vous enregistré.</p> : null}</div></Card></div><Card className="h-fit p-6"><span className="grid size-12 place-items-center rounded-[18px] bg-[var(--mint-soft)]"><Plus className="size-5" /></span><h2 className="mt-5 text-2xl font-semibold">Demander un créneau</h2><p className="mt-2 text-sm leading-6 text-[color:var(--muted)]">La demande reste « requested » jusqu’à confirmation par l’équipe.</p><div className="mt-6 space-y-4"><label className="block text-sm font-semibold">Date<input type="date" min={dateInputValue(firstPossibleDate)} value={date} onChange={(event) => setDate(event.target.value)} className="mt-2 h-12 w-full rounded-2xl border border-[var(--line)] px-4 font-normal" /></label><div className="grid grid-cols-2 gap-3"><label className="block text-sm font-semibold">Heure<input type="time" value={time} onChange={(event) => setTime(event.target.value)} className="mt-2 h-12 w-full rounded-2xl border border-[var(--line)] px-4 font-normal" /></label><label className="block text-sm font-semibold">Durée<select value={duration} onChange={(event) => setDuration(Number(event.target.value))} className="mt-2 h-12 w-full rounded-2xl border border-[var(--line)] bg-white px-4 font-normal"><option value={30}>30 min</option><option value={45}>45 min</option><option value={60}>60 min</option></select></label></div><label className="block text-sm font-semibold">Format<select value={type} onChange={(event) => setType(event.target.value as typeof type)} className="mt-2 h-12 w-full rounded-2xl border border-[var(--line)] bg-white px-4 font-normal"><option value="video">Visioconférence</option><option value="phone">Téléphone</option><option value="onsite">Sur place</option></select></label><label className="block text-sm font-semibold">Objectif ou contraintes<textarea rows={4} value={notes} onChange={(event) => setNotes(event.target.value)} className="mt-2 w-full rounded-2xl border border-[var(--line)] p-4 font-normal" placeholder="Sujets à préparer, contraintes horaires…" /></label>{mutation.error ? <p className="text-xs text-[color:var(--blue)]">{mutation.error instanceof Error ? mutation.error.message : "Demande impossible"}</p> : null}{mutation.isSuccess ? <p className="rounded-2xl bg-[var(--mint-soft)] p-3 text-sm font-semibold">Demande enregistrée ; elle attend une confirmation.</p> : null}<Button onClick={() => mutation.mutate()} disabled={mutation.isPending || !data?.project} className="w-full">{mutation.isPending ? "Enregistrement…" : "Envoyer la demande"}</Button></div></Card></div></div>;
}
